import { createHash } from 'node:crypto';

/**
 * Who is calling, when nobody signs in.
 *
 * There are no accounts and no licence keys any more, so the search API has no idea who
 * anyone is. These two values are what is left to tell one caller from another, and they
 * are what the rate limiter counts against — see lib/rateLimit.ts.
 *
 * Neither is trustworthy on its own, and that is the point of having both:
 *
 * - **The install id** is generated by the extension and sent in a header, so anyone can
 *   change it, and somebody determined will. It is precise (one browser profile) and
 *   forgeable.
 * - **The hashed IP** cannot be chosen by the caller, but is shared by everyone behind one
 *   NAT, so it must be limited far more loosely or a university dormitory becomes one user.
 *
 * Limiting on both means rotating the install id still runs into the address bucket, and a
 * shared address does not punish the people behind it for one abuser — each covers the
 * other's blind spot.
 */

/** The extension's anonymous per-install id, or null when the header is absent. */
export function installOf(request: Request): string | null {
  const raw = request.headers.get('x-subtitler-install')?.trim();
  if (!raw) return null;
  // Bounded before it reaches a database key: this string is chosen by the caller.
  return raw.slice(0, 64);
}

/**
 * A salted hash of the caller's address.
 *
 * Enough to notice one address making thousands of requests, without this becoming a store
 * of IP addresses. Unsalted would be trivially reversible — the whole IPv4 space hashes in
 * seconds — so `IP_HASH_SALT` is what makes the stored value meaningless on its own.
 */
export function hashIp(request: Request): string | null {
  // The first entry is the client; the rest are proxies that appended themselves.
  const forwarded = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim();
  const ip = forwarded || request.headers.get('x-real-ip')?.trim();
  if (!ip) return null;

  const salt = process.env.IP_HASH_SALT ?? '';
  return createHash('sha256').update(`${ip}:${salt}`).digest('hex').slice(0, 32);
}

/**
 * The subject a request is limited against.
 *
 * A caller sending no install id is **not** waved through — they land in one shared
 * `anonymous` bucket together. Treating a missing header as unlimited would make the
 * limiter opt-in, which is the same as not having one.
 */
export function callerSubjects(request: Request): { install: string; ip: string | null } {
  return {
    install: installOf(request) ?? 'anonymous',
    ip: hashIp(request),
  };
}
